<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { agentDateLabel, agentStatusLabel, emptyAgentPage, formatMoney, useAgentApi, useAgentActions, type AgentWallet, type AgentTransaction, type AgentRecharge } from '../lib/agentWorkbench'
import AgentPagination from './AgentPagination.vue'
const api = useAgentApi(), balances = ref<AgentWallet[]>([]), transactions = ref(emptyAgentPage<AgentTransaction>()), recharges = ref(emptyAgentPage<AgentRecharge>())
const profile = reactive({ companyName: '', contactName: '' }), currency = ref('USD'), loading = ref(false)
const currencies = ['USD','CNY','EUR','GBP','HKD','JPY','CAD','AUD','SGD']
const form = reactive({ currencyCode: 'USD', amount: '', providerCode: 'bank_transfer', payerReference: '', proofReference: '' })
const { busy, error, success, run } = useAgentActions()
async function loadTransactions(page = 1) { try { transactions.value = await api.fetchTransactions(currency.value, page) } catch (e) { error.value = e instanceof Error ? e.message : '余额流水加载失败。' } }
async function loadRecharges(page = 1) { try { recharges.value = await api.fetchRecharges(page) } catch (e) { error.value = e instanceof Error ? e.message : '充值记录加载失败。' } }
async function load() { loading.value = true; try { const [company, wallets] = await Promise.all([api.fetchMerchantProfile(),api.fetchWallets()]); Object.assign(profile,company); balances.value = wallets; await Promise.all([loadTransactions(),loadRecharges()]) } catch (e) { error.value = e instanceof Error ? e.message : '企业余额加载失败。' } finally { loading.value = false } }
async function saveProfile() { const payload = { ...profile }; await run('profile:save',payload,() => api.saveMerchantProfile(payload),() => {},'企业信息已保存。') }
async function recharge() { const payload = { ...form }; if (await run('recharge:create',payload,key => api.requestRecharge(payload,key),() => { form.amount='';form.payerReference='';form.proofReference='' },'充值已提交，核款后计入余额。')) await loadRecharges() }
onMounted(load)
</script>
<template><section data-testid="agent-wallet-panel"><div class="agent-toolbar"><h2>企业余额</h2><el-button :loading="loading" :disabled="busy" @click="load">刷新</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false" /><el-alert v-if="success" :title="success" type="success" :closable="false" /><div class="agent-wallet-balances"><article v-for="code in currencies" :key="code" class="agent-stock-card"><span>{{ code }}</span><strong>{{ formatMoney(balances.find(wallet => wallet.currencyCode === code)?.balance || 0,code) }}</strong></article></div><div class="form-grid"><form class="portal-form agent-operation" @submit.prevent="saveProfile"><h3>企业资料</h3><label>企业名称<input v-model="profile.companyName" required maxlength="191" :disabled="busy" /></label><label>联系人<input v-model="profile.contactName" required maxlength="128" :disabled="busy" /></label><button class="btn-primary" :disabled="busy">保存资料</button></form><form class="portal-form agent-operation" data-testid="agent-recharge-form" @submit.prevent="recharge"><h3>提交充值</h3><p class="muted-copy">按 NXR 提供的收款信息转账后，填写凭证申请核款。</p><fieldset :disabled="busy"><div class="form-grid"><label>币种<select v-model="form.currencyCode"><option v-for="code in currencies" :key="code">{{ code }}</option></select></label><label>金额<input v-model="form.amount" type="number" required :min="form.currencyCode === 'JPY' ? 1 : .01" :step="form.currencyCode === 'JPY' ? 1 : .01" max="99999999" /></label></div><label>转账方式<select v-model="form.providerCode"><option value="bank_transfer">银行转账</option><option value="wechat_transfer">微信转账</option><option value="alipay_transfer">支付宝转账</option></select></label><label>转账流水号<input v-model="form.payerReference" required maxlength="255" /></label><label>凭证说明（选填）<input v-model="form.proofReference" maxlength="512" /></label></fieldset><button class="btn-primary" :disabled="busy" data-testid="agent-submit-recharge">提交核款</button></form></div><h3>充值记录</h3><el-table :data="recharges.items" border><el-table-column prop="rechargeNo" label="充值单" min-width="180" /><el-table-column label="金额" min-width="130"><template #default="{row}">{{ formatMoney(row.amount,row.currencyCode) }}</template></el-table-column><el-table-column label="状态" min-width="130"><template #default="{row}">{{ agentStatusLabel(row.statusCode) }}</template></el-table-column><el-table-column prop="reviewNote" label="核款备注" min-width="180" /><el-table-column label="时间" min-width="170"><template #default="{row}">{{ agentDateLabel(row.createdAt) }}</template></el-table-column></el-table><AgentPagination v-bind="recharges" :disabled="busy" @change="loadRecharges" /><div class="agent-toolbar"><h3>余额流水</h3><el-select v-model="currency" style="width:130px" @change="loadTransactions()"><el-option v-for="code in currencies" :key="code" :value="code" :label="code" /></el-select></div><el-table :data="transactions.items" border><el-table-column label="时间" min-width="170"><template #default="{row}">{{ agentDateLabel(row.createdAt) }}</template></el-table-column><el-table-column label="金额" min-width="130"><template #default="{row}">{{ row.directionCode === 'debit' ? '−' : '+' }}{{ formatMoney(row.amount,currency) }}</template></el-table-column><el-table-column label="余额" min-width="130"><template #default="{row}">{{ formatMoney(row.balanceAfter,currency) }}</template></el-table-column><el-table-column prop="note" label="说明" min-width="220" /></el-table><AgentPagination v-bind="transactions" :disabled="busy" @change="loadTransactions" /></section></template>
